statement:
Call a contiguous, non-empty piece `s` of the integer array `nums` **alternating** when all of these hold:

- it has at least two elements;
- its second element is exactly one more than its first, `s[1] = s[0] + 1`;
- after that it keeps switching between those two values, `[s[0], s[0] + 1, s[0], s[0] + 1, ...]`, so the differences between neighbours are `+1, -1, +1, -1, ...` in that order.

Return the greatest length of an alternating subarray of `nums`, or `-1` when `nums` has none.

validator:
function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value is a whole number from 1 to 10000.';
  return null;
}

reference:
function alternatingSubarray(nums) {
  let best = -1;
  for (let start = 0; start + 1 < nums.length; start++) {
    if (nums[start + 1] - nums[start] !== 1) {
      continue;
    }
    let end = start + 1;
    while (end + 1 < nums.length && nums[end + 1] === nums[end - 1]) {
      end++;
    }
    best = Math.max(best, end - start + 1);
  }
  return best;
}

brute:
function alternatingSubarray(nums) {
  // Check every subarray of length at least 2 against the pattern low, low + 1, low, low + 1, ...
  let answer = -1;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      let ok = true;
      for (let t = 0; t <= j - i; t++) {
        if (nums[i + t] !== nums[i] + (t % 2)) ok = false;
      }
      if (ok) answer = Math.max(answer, j - i + 1);
    }
  }
  return answer;
}

generator:
function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 9);
  const top = rand() < 0.2 ? 10000 : 6;
  const nums = [];
  // Mix alternating runs with single values so runs get cut and restarted.
  while (nums.length < n) {
    const low = 1 + Math.floor(rand() * (top - 1));
    if (rand() < 0.5) {
      const run = 1 + Math.floor(rand() * (size === 'large' ? 30 : 6));
      for (let i = 0; i < run && nums.length < n; i++) nums.push(low + (i % 2));
    } else {
      nums.push(low);
    }
  }
  return [nums];
}
